// Generated by MuseSwarm (@builder) — Isomorphic Core Engine with SLA Breach Detector
class TaskPriorityEngine {
  constructor() {
    this.items = [];
    this.counter = 0;
  }

  addItem({ title, impact = 5, urgency = 5, effort = 3, slaMinutes = 60, elapsedMinutes = 0, owner = '@builder' }) {
    if (!title || typeof title !== 'string' || !title.trim()) {
      throw new Error('Title is required');
    }
    const cleanImpact = Math.max(1, Math.min(10, Number(impact) || 5));
    const cleanUrgency = Math.max(1, Math.min(10, Number(urgency) || 5));
    const cleanEffort = Math.max(1, Math.min(10, Number(effort) || 3));
    const cleanSla = Math.max(5, Number(slaMinutes) || 60);
    const cleanElapsed = Math.max(0, Number(elapsedMinutes) || 0);
    const breached = cleanElapsed > cleanSla;
    const slaBoost = breached ? 5 : 0;
    const score = Number(((((cleanImpact * 1.6) + (cleanUrgency * 1.4)) / Math.sqrt(cleanEffort)) + slaBoost).toFixed(2));

    this.counter += 1;
    const item = {
      id: 'item-' + this.counter,
      title: title.trim(),
      impact: cleanImpact,
      urgency: cleanUrgency,
      effort: cleanEffort,
      slaMinutes: cleanSla,
      elapsedMinutes: cleanElapsed,
      breached,
      owner: String(owner || '@builder').replace(/[<>]/g, ''),
      score,
      status: 'open',
    };
    this.items.push(item);
    return item;
  }

  checkSLA(id, elapsedMinutes) {
    const found = this.items.find((i) => i.id === id);
    if (!found) throw new Error('Item not found: ' + id);
    found.elapsedMinutes = Math.max(0, Number(elapsedMinutes) || 0);
    const wasBreached = found.breached;
    found.breached = found.status !== 'done' && found.elapsedMinutes > found.slaMinutes;
    if (found.breached && !wasBreached) {
      found.score = Number((found.score + 5).toFixed(2));
    }
    return found;
  }

  getBreachedItems() {
    return this.items.filter((i) => i.status !== 'done' && i.breached);
  }

  getRankedItems() {
    return [...this.items].sort((a, b) => b.score - a.score);
  }

  completeItem(id) {
    const found = this.items.find((i) => i.id === id);
    if (!found) throw new Error('Item not found: ' + id);
    found.status = 'done';
    found.breached = false;
    return found;
  }

  getSummary() {
    const total = this.items.length;
    const done = this.items.filter((i) => i.status === 'done').length;
    const breachedCount = this.getBreachedItems().length;
    const top = this.getRankedItems()[0] || null;
    return {
      total,
      done,
      open: total - done,
      breachedCount,
      topPriority: top ? top.title : null,
    };
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { TaskPriorityEngine };
}
if (typeof globalThis !== 'undefined') {
  globalThis.AppCore = { TaskPriorityEngine };
}
